import{_ as o,o as t,c as a,a0 as i}from"./chunks/framework.DCToIpx6.js";const p=JSON.parse('{"title":"Proposal: Generic Table Column Enhancement","description":"","frontmatter":{},"headers":[],"relativePath":"changes/archive/2026-06-05-generic-table-column-enhancement/proposal.md","filePath":"changes/archive/2026-06-05-generic-table-column-enhancement/proposal.md"}'),l={name:"changes/archive/2026-06-05-generic-table-column-enhancement/proposal.md"};function c(n,e,d,r,s,h){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="proposal-generic-table-column-enhancement" tabindex="-1">Proposal: Generic Table Column Enhancement <a class="header-anchor" href="#proposal-generic-table-column-enhancement" aria-label="Permalink to &quot;Proposal: Generic Table Column Enhancement&quot;">​</a></h1><h2 id="intent" tabindex="-1">Intent <a class="header-anchor" href="#intent" aria-label="Permalink to &quot;Intent&quot;">​</a></h2><p><code>TableColumn</code> currently only carries <code>key</code> + <code>header</code>. The <code>GenericTableWithoutActionsComponent</code> iterates all columns with no conditional rendering, no click handling, and a global filter that searches every column. We need backend-driven column configuration: visibility, tooltips, click actions, and filterable control — without breaking existing usage.</p><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><h3 id="in-scope" tabindex="-1">In Scope <a class="header-anchor" href="#in-scope" aria-label="Permalink to &quot;In Scope&quot;">​</a></h3><ul><li>Extend <code>TableColumn</code> interface with <code>visible</code>, <code>tooltip</code>, <code>clickeable</code>, <code>filterable</code></li><li>Filter <code>displayedColumns</code> by <code>visible</code> (backward-compatible: default <code>true</code>)</li><li>Render <code>matTooltip</code> on cells when <code>tooltip</code> is set</li><li>Emit <code>cellClick</code> event on click when <code>clickeable</code> is true; delegate action to parent</li><li>Custom <code>filterPredicate</code> on <code>MatTableDataSource</code> to search only <code>filterable</code> columns</li><li>Import <code>MatTooltipModule</code> where needed</li></ul><h3 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h3><ul><li>Other table components or existing functionality</li><li>Tests (user disabled Strict TDD)</li><li>Column reordering, resizing, or sorting</li><li>New filter UI (reuses existing global search input)</li><li>Column grouping or aggregation</li></ul><h2 id="capabilities" tabindex="-1">Capabilities <a class="header-anchor" href="#capabilities" aria-label="Permalink to &quot;Capabilities&quot;">​</a></h2><h3 id="new-capabilities" tabindex="-1">New Capabilities <a class="header-anchor" href="#new-capabilities" aria-label="Permalink to &quot;New Capabilities&quot;">​</a></h3><ul><li><code>dynamic-column-config</code>: Column-level properties (<code>visible</code>, <code>tooltip</code>, <code>clickeable</code>, <code>filterable</code>) that control rendering, interaction, and filter behavior</li></ul><h3 id="modified-capabilities" tabindex="-1">Modified Capabilities <a class="header-anchor" href="#modified-capabilities" aria-label="Permalink to &quot;Modified Capabilities&quot;">​</a></h3><ul><li>None — no existing specs in <code>openspec/specs/</code></li></ul><h2 id="approach" tabindex="-1">Approach <a class="header-anchor" href="#approach" aria-label="Permalink to &quot;Approach&quot;">​</a></h2><ol><li><strong>Interface</strong> — Add 4 optional booleans + optional string to <code>TableColumn</code></li><li><strong>displayedColumns</strong> — Filter by <code>visible</code> in <code>ngOnChanges</code>; skip non-visible column keys</li><li><strong>Filter</strong> — Set <code>dataSource.filterPredicate</code> to iterate only columns where <code>filterable !== false</code>; apply existing <code>filter.trim().toLowerCase()</code> match on cell values</li><li><strong>Template</strong> — Conditionally add <code>[matTooltip]</code>, <code>(click)</code>, and <code>[style.cursor]</code> based on column config</li><li><strong>Output</strong> — Add <code>@Output() cellClick = new EventEmitter&lt;{ column: TableColumn; row: any }&gt;()</code>; parent handles navigation/modal</li><li><strong>Module</strong> — Verify <code>MatTooltipModule</code> is imported in the parent module</li></ol><h2 id="affected-areas" tabindex="-1">Affected Areas <a class="header-anchor" href="#affected-areas" aria-label="Permalink to &quot;Affected Areas&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Impact</th><th>Description</th></tr></thead><tbody><tr><td><code>src/.../interfaces/tableColumn.interface.ts</code></td><td>Modified</td><td>Add 4 new optional props</td></tr><tr><td><code>src/.../generic-table-without-actions.component.ts</code></td><td>Modified</td><td>filterPredicate, cellClick output, visible filtering</td></tr><tr><td><code>src/.../generic-table-without-actions.component.html</code></td><td>Modified</td><td>Conditional tooltip, click, cursor per column</td></tr></tbody></table><h2 id="risks" tabindex="-1">Risks <a class="header-anchor" href="#risks" aria-label="Permalink to &quot;Risks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Risk</th><th>Likelihood</th><th>Mitigation</th></tr></thead><tbody><tr><td>Backward compat: new props are optional, but old code without <code>filterable</code> defaults to all-column search</td><td>Low</td><td>Default <code>filterable</code> to <code>true</code> when undefined</td></tr><tr><td>Missing <code>MatTooltipModule</code> breaks build</td><td>Low</td><td>Verify module import before closing</td></tr><tr><td><code>clickeable</code> delegates to parent but needs <code>Output</code> subscription detail</td><td>Med</td><td>Document event payload in spec phase</td></tr></tbody></table><h2 id="rollback-plan" tabindex="-1">Rollback Plan <a class="header-anchor" href="#rollback-plan" aria-label="Permalink to &quot;Rollback Plan&quot;">​</a></h2><p><code>git revert &lt;merge-commit&gt;</code> to undo the entire change. If partial rollback needed, restore the 3 affected files from <code>git checkout HEAD~1 -- &lt;file&gt;</code>.</p><h2 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to &quot;Dependencies&quot;">​</a></h2><ul><li><code>@angular/material</code> <code>MatTooltipModule</code> (already in project)</li></ul><h2 id="success-criteria" tabindex="-1">Success Criteria <a class="header-anchor" href="#success-criteria" aria-label="Permalink to &quot;Success Criteria&quot;">​</a></h2><ul><li>[ ] <code>TableColumn</code> has the 4 new properties; existing interfaces compile without changes</li><li>[ ] Columns with <code>visible: false</code> are absent from the rendered table</li><li>[ ] Clickable cells emit <code>{ column, row }</code> on click; parent receives the event</li><li>[ ] Tooltip columns show <code>matTooltip</code> on cell hover</li><li>[ ] Global filter matches only <code>filterable: true</code> columns (or all when undefined)</li><li>[ ] Existing table instances render identically with no errors</li></ul>',25)])])}const b=o(l,[["render",c]]);export{p as __pageData,b as default};
